// Season 1 lock, server side. Generated by site/layers/season_rebase/apply_season.py from season.json: edit there.
// Before launch (or with force "locked") every gated game page is served as the lock panel only, uncached, noindex.
// After launch, an episode whose data-open time is still ahead is served without its game. ?preview=1 skips the gates
// on non-production hosts only (the dev project, its preview branches, review, localhost).
const S = {"launch": "2026-11-16T17:00:00Z", "force": "locked", "gated": ["arcade", "tracewire", "daily", "leak", "deal", "quiz", "ep1", "ep2", "ep3", "ep4", "ep5", "ep6", "ep7", "ep8", "ep9"]};
const GATED = new Set(S.gated);
const PREVIEW_HOST = /^(review\.themarginwars\.pages\.dev|([a-z0-9-]+\.)?themarginwars-dev\.pages\.dev|localhost|127\.0\.0\.1)$/;
const PT = new Intl.DateTimeFormat("en-US", { timeZone: "America/Los_Angeles", weekday: "short", month: "short", day: "numeric" });
function seasonLocked(now, preview) {
  if (preview) return false;
  if (S.force === "locked") return true;
  if (S.force === "open") return false;
  return now < Date.parse(S.launch);
}
function epLock(iso) {
  return '<p class="lock">\u{1F512} This episode opens in <b data-drop="' + iso + '">' + PT.format(new Date(iso)) + ", 9:00 AM PT</b>. Play the <a href=\"daily.html\">Daily</a> while you wait.</p>";
}
export async function onRequest(ctx) {
  const url = new URL(ctx.request.url);
  const name = url.pathname.replace(/^\/+|\/+$/g, "").replace(/\.html$/, "");
  if (!GATED.has(name) || !["GET", "HEAD"].includes(ctx.request.method)) return ctx.next();
  const req = new Request(ctx.request);
  req.headers.delete("if-none-match");
  req.headers.delete("if-modified-since");
  const res = await ctx.next(req);
  if (res.status !== 200 || !(res.headers.get("content-type") || "").includes("text/html")) return res;
  const now = Date.now();
  const preview = url.searchParams.get("preview") === "1" && PREVIEW_HOST.test(url.hostname);
  const locked = seasonLocked(now, preview);
  const rw = new HTMLRewriter().on("html", {
    element(e) {
      e.setAttribute("data-s1", locked ? "locked" : preview ? "preview" : "open");
      if (locked) e.setAttribute("class", ((e.getAttribute("class") || "") + " s1-on").trim());
    },
  });
  if (locked) {
    rw.on("main > *:not(#s1-lock)", { element(e) { e.remove(); } })
      .on("template#s1-lock", { element(e) { e.removeAndKeepContent(); } });
  } else {
    rw.on("template#s1-lock", { element(e) { e.remove(); } })
      .on('section[data-game="ep"][data-open]', {
        element(e) {
          const t = e.getAttribute("data-open");
          if (!preview && now < Date.parse(t)) { e.removeAttribute("data-game"); e.setInnerContent(epLock(t), { html: true }); }
        },
      })
      .on("[data-s1-open]", {
        element(e) { if (preview || now >= Date.parse(e.getAttribute("data-s1-open"))) e.setInnerContent("Open"); },
      });
  }
  const out = rw.transform(res);
  const h = new Headers(out.headers);
  h.delete("etag");
  h.delete("last-modified");
  h.set("cache-control", "no-store");
  if (locked) h.set("x-robots-tag", "noindex");
  return new Response(out.body, { status: out.status, headers: h });
}
